    "purpose": "Bu dersin amacı, idarenin mali sorumluluğunun teorik ve hukuki temellerini, sorumluluk türlerini, kamu zararının belirlenmesi ve tazmini süreçlerini, yargısal denetimi ve uygulamadaki güncel gelişmeleri ayrıntılı biçimde incelemektir. Öğrencilerin, idari eylem ve işlemlerden doğan mali yükümlülükleri kapsamlı bir şekilde analiz edebilmesi, uyuşmazlık çözüm yollarını değerlendirebilmesi ve alana ilişkin akademik araştırma yapabilecek düzeye ulaşması hedeflenmektedir.",
    "content": "Bu derste; idarenin mali sorumluluğunun kavramsal çerçevesi, tarihsel gelişimi, hukuki dayanakları, kusurlu ve kusursuz sorumluluk türleri, kamu zararının tespiti ve tazmini, hizmet kusuru ve risk sorumluluğu ilkeleri, yargısal denetim mekanizmaları, Danıştay ve Anayasa Mahkemesi içtihatları, karşılaştırmalı hukuk örnekleri ile güncel uygulama sorunları ele alınacaktır. Ayrıca öğrenciler, idarenin mali sorumluluğuna ilişkin akademik metinleri yorumlayacak ve örnek olaylar üzerinden çözüm önerileri geliştirecektir.",
